import{_ as e,o,c as t,a0 as d}from"./chunks/framework.BGyYNsHo.js";const p=JSON.parse('{"title":"Componentes del modelo hidráulico","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/hidraulica/02-componentes-del-modelo.md","filePath":"es/explanation/hidraulica/02-componentes-del-modelo.md"}'),l={name:"es/explanation/hidraulica/02-componentes-del-modelo.md"};function n(r,a,i,m,s,c){return o(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="componentes-del-modelo-hidraulico" tabindex="-1">Componentes del modelo hidráulico <a class="header-anchor" href="#componentes-del-modelo-hidraulico" aria-label="Permalink to &quot;Componentes del modelo hidráulico&quot;">​</a></h1><h2 id="datos-de-los-nodos" tabindex="-1">Datos de los nodos <a class="header-anchor" href="#datos-de-los-nodos" aria-label="Permalink to &quot;Datos de los nodos&quot;">​</a></h2><p>Cada nodo lleva propiedades geométricas estáticas y estado dinámico (<code>NodeData.hpp</code>):</p><ul><li>$z_{\\mathrm{inv}}$ — cota de batea (ft).</li><li>$d_{\\mathrm{full}}$ — profundidad total (tirante hasta el brocal / borde superior del estanque).</li><li>$d_{\\mathrm{sur}}$ — profundidad máxima admisible de escurrimiento en carga sobre la profundidad total; el límite de anegamiento es $z_{\\mathrm{inv}} + d_{\\mathrm{full}} + d_{\\mathrm{sur}}$.</li><li>$A_{\\mathrm{pond}}$ — área de encharcamiento usada cuando el nodo se anega sobre el brocal y el encharcamiento está habilitado.</li><li>$z_{\\mathrm{crown}}$ — cota de la clave del conducto más alto conectado; el umbral de entrada en carga es $y_{\\mathrm{crown}} = z_{\\mathrm{crown}} - z_{\\mathrm{inv}}$.</li><li>$\\mathrm{deg}$ — número de enlaces conectados; si es negativo, el nodo es un nodo terminal aguas arriba.</li><li>$V_{\\mathrm{full}}$ — volumen a profundidad total.</li></ul><p>Estado dinámico (actualizado en cada paso de tránsito):</p><ul><li>$d$ — tirante de agua sobre la batea (ft);</li><li>$H = z_{\\mathrm{inv}} + d$ — carga hidráulica (ft);</li><li>$V$ — volumen almacenado (ft³);</li><li>$Q_{\\mathrm{lat}}$ — aporte lateral total (ft³/s);</li><li>$Q_{\\mathrm{in}}$, $Q_{\\mathrm{out}}$ — ingreso y salida totales;</li><li>$Q_{\\mathrm{ovfl}}$ — tasa de rebalse/anegamiento;</li><li>$Q_{\\mathrm{loss}}$ — tasa de pérdidas por evaporación + filtración/exfiltración;</li><li>$\\Delta Q_{\\mathrm{net}}^{t-1}$ — ingreso neto $Q_{\\mathrm{in}} - Q_{\\mathrm{out}}$ del paso anterior (usado para el promediado trapezoidal);</li><li>valores del paso anterior $d^{t-1}$, $V^{t-1}$, $Q_{\\mathrm{lat}}^{t-1}$.</li></ul><h3 id="funciones-de-area-superficial-y-volumen-de-los-nodos" tabindex="-1">Funciones de área superficial y volumen de los nodos <a class="header-anchor" href="#funciones-de-area-superficial-y-volumen-de-los-nodos" aria-label="Permalink to &quot;Funciones de área superficial y volumen de los nodos&quot;">​</a></h3><p>Las funciones de geometría de nodo están implementadas en <code>src/engine/hydraulics/Node.cpp</code>.</p><p><strong>Volumen de cámara de unión / emisario / divisor</strong>: con $\\mathrm{MIN_SURFAREA} = 12.566\\ \\mathrm{ft^2}$ ($\\approx 4\\pi$, el área de una cámara de inspección de 4 pies),</p><p>$$V(d) = V_{\\mathrm{full}},\\frac{d}{d_{\\mathrm{full}}},$$</p><p>donde $V_{\\mathrm{full}} = \\mathrm{MIN_SURFAREA}\\cdot d_{\\mathrm{full}}$ salvo que se haya redefinido.</p><p><strong>Volumen del estanque de almacenamiento</strong>:</p><ul><li>Tabular: $V = \\mathrm{table}(d\\cdot \\mathrm{Ucf}[L])/\\mathrm{Ucf}[V]$ con interpolación de tabla;</li><li>Las formas geométricas (cilíndrica, cónica, paraboloide, piramidal) usan la relación cuadrática de área superficial $A(d) = c + a,d + b,d^{2}$, integrada al polinomio cúbico</li></ul><p>$$V(d) = d\\left(c + d!\\left(\\tfrac{a}{2} + d,\\tfrac{b}{3}\\right)\\right);$$</p><ul><li>Almacenamiento funcional: ley de potencia $A(d) = c + a,d^{b}$ integrada analíticamente.</li></ul><p><strong>Área superficial</strong> $A_{\\mathrm{surf}}(d)$: los nodos no-estanque retornan 0 (el piso de área mínima se aplica más adelante en la actualización de nodo de la onda dinámica); los estanques retornan el valor de la tabla (extrapolando linealmente) o la forma analítica $A(d) = c + a,d + b,d^{2}$ / $A(d) = c + a,d^{b}$.</p><p><strong>Área de encharcamiento</strong>:</p><p>$$A_{\\mathrm{pond}}(d) = \\begin{cases} A_{\\mathrm{surf}}(d) &amp; d \\le d_{\\mathrm{full}} \\text{ o } A_{\\mathrm{pond}} = 0,\\ A_{\\mathrm{pond}} &amp; d &gt; d_{\\mathrm{full}} \\text{ (anegado)}. \\end{cases}$$</p><p><strong>Tirante a partir del volumen</strong> (la inversa de la función de volumen, usada por la actualización de estanque de la onda cinemática y por los reportes): los nodos cámara de unión usan $d = V/\\mathrm{MIN_SURFAREA}$; los estanques invierten las relaciones tabular/geométrica/funcional, usando Newton–Raphson con fallback de bisección cuando no existe forma cerrada.</p><p><strong>Caudal máximo de salida</strong> (usado por la reunión de ingreso de enlace de la onda cinemática y del escurrimiento permanente):</p><p>$$Q_{\\max} = Q_{\\mathrm{in}} + \\frac{V_{\\mathrm{old}}}{dt}, \\qquad Q_{\\mathrm{in}} = \\min!\\left(Q_{\\mathrm{in}}, Q_{\\max}\\right).$$</p><h2 id="datos-de-los-enlaces" tabindex="-1">Datos de los enlaces <a class="header-anchor" href="#datos-de-los-enlaces" aria-label="Permalink to &quot;Datos de los enlaces&quot;">​</a></h2><p>Cada enlace lleva propiedades estáticas y estado dinámico (<code>LinkData.hpp</code>). Para los conductos, los parámetros de capacidad de conducción por enlace (por barril) son (<code>Link.cpp</code>, <code>computeConveyance</code>):</p><p>$$ \\begin{aligned} \\beta &amp;= \\frac{\\mathrm{PHI},\\sqrt{|S_0|}}{n}, \\qquad \\mathrm{PHI} = 1.486 \\quad\\text{(factor US de Manning)}, \\ \\mathrm{rough_factor} &amp;= g\\left(\\frac{n}{\\mathrm{PHI}}\\right)^{2},\\ Q_{\\mathrm{full}} &amp;= S_{\\mathrm{full}}\\cdot\\beta, \\qquad Q_{\\max} = S_{\\max}\\cdot\\beta, \\end{aligned} $$</p><p>donde $n$ es la rugosidad de Manning, $S_0$ la pendiente del conducto, $S(a) = A,R^{2/3}$ el <em>factor de sección</em> (ver Sección 4), $S_{\\mathrm{full}} = S(A_{\\mathrm{full}})$ y $S_{\\max} = \\max_a S(a)$.</p><p>Estado dinámico por enlace: $Q$ (caudal actual, $+$ = nodo1→nodo2), $d$ (tirante medio), $V$ (volumen), $\\mathrm{Fr}$ (número de Froude), $\\mathrm{flow_class}$ (DRY, UP_DRY, DN_DRY, SUBCRITICAL, SUPERCRITICAL, UP_CRITICAL, DN_CRITICAL) y valores del paso anterior.</p><h2 id="pendiente-y-longitud-del-conducto" tabindex="-1">Pendiente y longitud del conducto <a class="header-anchor" href="#pendiente-y-longitud-del-conducto" aria-label="Permalink to &quot;Pendiente y longitud del conducto&quot;">​</a></h2><p>Para un conducto que conecta los nodos $i$ y $j$ con elevaciones de extremo $z_1, z_2$, las cotas de batea de los extremos del conducto son $Z_1 = z_{\\mathrm{inv},1} + z_1$, $Z_2 = z_{\\mathrm{inv},2} + z_2$. La pendiente del conducto es</p><p>$$S_0 = \\frac{\\Delta y}{\\Delta x}, \\qquad \\Delta y = Z_1 - Z_2, \\quad \\Delta x = \\sqrt{L^{2} - \\Delta y^{2}},$$</p><p>con un desnivel mínimo impuesto de $\\lvert \\Delta y \\rvert \\ge 0.001\\ \\mathrm{ft}$ (sobrescribible).</p><h2 id="alargamiento-de-conductos-estabilidad-de-courant" tabindex="-1">Alargamiento de conductos (estabilidad de Courant) <a class="header-anchor" href="#alargamiento-de-conductos-estabilidad-de-courant" aria-label="Permalink to &quot;Alargamiento de conductos (estabilidad de Courant)&quot;">​</a></h2><p>Si se entrega un <code>LENGTHENING_STEP</code> positivo, los conductos cortos se alargan artificialmente para que se cumpla la condición de Courant para el paso de tiempo entregado por el usuario (<code>Routing.cpp:135–195</code>):</p><p>$$t_{\\mathrm{step}} = \\min(\\mathrm{routing_step},\\ \\mathrm{lengthening_step}), \\qquad v_{\\mathrm{full}} = \\frac{\\mathrm{PHI}}{n},\\frac{S_{\\mathrm{full}}}{\\sqrt{|S_0|},A_{\\mathrm{full}}},$$</p><p>$$\\mathrm{ratio} = \\frac{\\left(\\sqrt{g,y_{\\mathrm{full}}} + v_{\\mathrm{full}}\\right) t_{\\mathrm{step}}}{L}, \\qquad L&#39; = \\max(L,\\ \\mathrm{ratio}\\cdot L),$$</p><p>En canales abiertos, $y_{\\mathrm{full}}$ se reemplaza por el tirante hidráulico $A_{\\mathrm{full}}/W_{\\max}$. Si $L&#39; &gt; L$, la pendiente y la rugosidad se ajustan para preservar igual pérdida de carga a cualquier caudal,</p><p>$$S_0&#39; = \\frac{|S_0|}{L&#39;/L}, \\qquad n&#39; = \\frac{n}{\\sqrt{L&#39;/L}},$$</p><p>y $\\beta$, $\\mathrm{rough_factor}$, $Q_{\\mathrm{full}}$, $Q_{\\max}$ se recalculan a partir de los valores ajustados. La longitud alargada $L&#39;$ (<code>mod_length</code>) se usa en la ecuación de momentum; la longitud cruda $L$ se usa para la contabilidad de volúmenes.</p>',37)])])}const $=e(l,[["render",n]]);export{p as __pageData,$ as default};
